(() => { const A = window.__CITY_APP, scene = A.scene; const vis = (o) => { for (let p = o; p; p = p.parent) if (!p.visible) return false; return true; };
 const by = {}; let shadowProxyTris = 0, proxies = 0;
 scene.traverse((o) => { if (!o.isMesh || !vis(o)) return; const g = o.geometry; const tri = (g.index ? g.index.count : g.attributes.position.count) / 3; const dr = g.drawRange; const n = Math.min(tri, dr.count === Infinity ? tri : dr.count / 3) * (o.isInstancedMesh ? o.count : 1);
  const key = (o.name || o.type) + (o.castShadow ? ' [casts]' : ''); const k = by[key] || (by[key] = { meshes: 0, tris: 0, verts: 0 }); k.meshes++; k.tris += n; k.verts += (g.attributes.position.count) * (o.isInstancedMesh ? o.count : 1);
  if (o.name === 'ShadowProxy') { proxies++; shadowProxyTris += n; } });
 const rows = Object.entries(by).sort((a, b) => b[1].tris - a[1].tris).slice(0, 25).map(([k, v]) => [k, v.meshes, Math.round(v.tris), Math.round(v.verts)]);
 return { rows, proxies, shadowProxyTris: Math.round(shadowProxyTris) }; })()

